<?php declare(strict_types=1); use Kulturhus\Verein\MemberChangeRequests;$changeQuery=$changeUi['source'];?>
<section class="card" data-member-change-list><h2><?=e($changeText($reviewChanges?'Eingereichte Änderungen':'Meine Änderungsanträge'))?></h2>
<form method="get" class="member-change-filter"><?=hidden('view',$changeBase['view']).hidden('tab','changes')?><label><?=e($changeText('Mitglied suchen'))?><input class="form-control" type="search" name="q" maxlength="150" value="<?=e($changeQuery['q'])?>" placeholder="<?=e($changeText('Vor- oder Nachname'))?>"></label><label><?=e($changeText('Status'))?><select class="form-control" name="state"><?php foreach([''=>'Alle']+MemberChangeRequests::STATES as$state=>$label):?><option value="<?=e($state)?>" <?=$changeQuery['state']===$state?'selected':''?>><?=e($changeText($label))?></option><?php endforeach?></select></label><button class="btn btn-outline theme-secondary"><?=e($changeText('Anzeigen'))?></button></form>
<p><?=e($changeText('{count} Anträge · Seite {page} / {pages}',['count'=>$changeUi['total'],'page'=>$changeUi['page'],'pages'=>$changeUi['pages']]))?></p>
<?php foreach($changeUi['rows']as$row):$changeCreated=localDateTime($row['created_at']);?><a class="member-change-row" href="<?=e($changeUrl(['change'=>$row['id']]))?>"><strong><?=e($reviewChanges?$row['name']:$changeText('Änderung vom {date}',['date'=>dateDe(substr($changeCreated,0,10))]))?></strong><span><?=e($changeText(MemberChangeRequests::STATES[$row['state']]))?></span><small><?=e(dateDe(substr($changeCreated,0,10)).' · '.timeDe($row['created_at']))?></small></a><?php endforeach?>
<?php if($changeUi['rows']===[]):?><p><?=e($changeText($reviewChanges?'Keine passenden Änderungsanträge.':'Du hast noch keine Änderungen eingereicht.'))?></p><?php endif?>
<?php if($changeUi['pages']>1):?><nav class="actions" aria-label="<?=e($changeText('Änderungsanträge'))?>"><?php foreach([-1=>'← Zurück',1=>'Weiter →']as$direction=>$label):$next=$changeUi['page']+$direction;if($next<1||$next>$changeUi['pages'])continue;?><a class="btn btn-outline theme-secondary" href="<?=e($changeUrl(['q'=>$changeQuery['q'],'state'=>$changeQuery['state'],'page'=>$next]))?>"><?=e($changeText($label))?></a><?php endforeach?><form method="get"><?=hidden('view',$changeBase['view']).hidden('tab','changes').hidden('q',$changeQuery['q']).hidden('state',$changeQuery['state'])?><label><?=e($changeText('Seite'))?><input class="form-control" name="page" type="number" min="1" max="<?=$changeUi['pages']?>" value="<?=$changeUi['page']?>" required></label><button class="btn btn-outline theme-secondary"><?=e($changeText('Seite öffnen'))?></button></form></nav><?php endif?></section>
